from decimal import Decimal
from fractions import Fraction
from typing import Any


def _number(value: Any) -> Fraction:
    """Convert a legacy numeric value to an exact rational value."""
    if value is None:
        return Fraction(0)

    if isinstance(value, str):
        value = value.strip()
        if not value:
            return Fraction(0)
        return Fraction(Decimal(value))

    if isinstance(value, Fraction):
        return value

    if isinstance(value, Decimal):
        return Fraction(value)

    if isinstance(value, bool):
        return Fraction(int(value))

    if isinstance(value, int):
        return Fraction(value)

    if isinstance(value, float):
        return Fraction(Decimal(str(value)))

    return Fraction(Decimal(str(value)))


def _primary_key(value: Any) -> tuple[int, Any]:
    """Provide deterministic ascending ordering for ordinary CRM key values."""
    if isinstance(value, bool):
        return (0, Fraction(int(value)))
    if isinstance(value, (int, float, Decimal, Fraction)):
        return (0, _number(value))
    if value is None:
        return (1, "")
    return (1, str(value))


def sweep(
    accounts: list[dict], orders: list[dict]
) -> tuple[list[dict], list]:
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[str, Any]] = []

    eligible_indexes = [
        index
        for index, account in enumerate(accounts)
        if account.get("DEL_FLG") != "Y" and account.get("ACCT_TYP") == "C"
    ]
    eligible_indexes.sort(
        key=lambda index: _primary_key(accounts[index].get("ACCT_ID"))
    )

    for index in eligible_indexes:
        source_account = accounts[index]
        new_account = new_accounts[index]
        acct_id = source_account.get("ACCT_ID")

        exposure = Fraction(0)
        for order in orders:
            if (
                order.get("ACCT_ID") == acct_id
                and order.get("DEL_FLG") != "Y"
                and order.get("STAT_CD") == "I"
            ):
                exposure += _number(order.get("TOT_AMT"))

        credit_limit = _number(source_account.get("CRED_LIMIT"))

        if exposure > credit_limit and new_account.get("CRED_HOLD") != "Y":
            new_account["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", acct_id))

        if (
            exposure <= credit_limit * Fraction(8, 10)
            and new_account.get("CRED_HOLD") == "Y"
        ):
            new_account["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", acct_id))

    return new_accounts, audits
